      "text": "ჩვენ ხშირად გვგონია, რომ შესაძლებლობა კარზე აკაკუნებს. სინამდვილეში კი შესაძლებლობა თითქმის ყოველთვის ჩუმად მოდის, ის არ ყვირის: \"აი, შენი შანსი!\" ის ჩვეულებრივ სამუშაო დღედ არის გადაცმული."
